/* Midnight Bloom Theme — Tailwind v3 (rgb) */
/* Channel triplets — consume via rgb(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Midnight Bloom Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 248 248 248;
    --foreground: 51 51 51;
    --card: 255 255 255;
    --card-foreground: 51 51 51;
    --popover: 255 255 255;
    --popover-foreground: 51 51 51;
    --primary: 109 93 231;
    --primary-foreground: 255 255 255;
    --secondary: 162 200 240;
    --secondary-foreground: 51 51 51;
    --muted: 201 196 182;
    --muted-foreground: 111 111 111;
    --accent: 140 148 107;
    --accent-foreground: 255 255 255;
    --destructive: 241 68 68;
    --destructive-foreground: 255 255 255;
    --border: 212 212 212;
    --input: 212 212 212;
    --ring: 109 93 231;
    --chart-1: 109 93 231;
    --chart-2: 143 69 174;
    --chart-3: 75 0 131;
    --chart-4: 99 148 235;
    --chart-5: 70 131 181;
    --radius: 0.5rem;
    --sidebar: 248 248 248;
    --sidebar-foreground: 51 51 51;
    --sidebar-primary: 109 93 231;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 140 148 107;
    --sidebar-accent-foreground: 255 255 255;
    --sidebar-border: 212 212 212;
    --sidebar-ring: 109 93 231;
    --font-sans: Montserrat, sans-serif;
    --font-serif: Playfair Display, serif;
    --font-mono: Source Code Pro, monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 0.1;
    --shadow-blur: 10px;
    --shadow-spread: -2px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 5px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 5px 10px -2px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0px 5px 10px -2px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
    --shadow:
      0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 2px 4px -3px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 4px 6px -3px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 8px 10px -3px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0px 5px 10px -2px hsl(0 0% 0% / 0.25);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 27 29 34;
    --foreground: 228 228 228;
    --card: 46 52 55;
    --card-foreground: 228 228 228;
    --popover: 46 52 55;
    --popover-foreground: 228 228 228;
    --primary: 109 93 231;
    --primary-foreground: 255 255 255;
    --secondary: 75 0 131;
    --secondary-foreground: 228 228 228;
    --muted: 69 69 69;
    --muted-foreground: 164 164 164;
    --accent: 99 148 235;
    --accent-foreground: 228 228 228;
    --destructive: 241 68 68;
    --destructive-foreground: 255 255 255;
    --border: 69 69 69;
    --input: 69 69 69;
    --ring: 109 93 231;
    --chart-1: 109 93 231;
    --chart-2: 143 69 174;
    --chart-3: 75 0 131;
    --chart-4: 99 148 235;
    --chart-5: 70 131 181;
    --radius: 0.5rem;
    --sidebar: 27 29 34;
    --sidebar-foreground: 228 228 228;
    --sidebar-primary: 109 93 231;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 99 148 235;
    --sidebar-accent-foreground: 228 228 228;
    --sidebar-border: 69 69 69;
    --sidebar-ring: 109 93 231;
    --font-sans: Montserrat, sans-serif;
    --font-serif: Playfair Display, serif;
    --font-mono: Source Code Pro, monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 0.1;
    --shadow-blur: 10px;
    --shadow-spread: -2px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 5px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 5px 10px -2px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0px 5px 10px -2px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
    --shadow:
      0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 2px 4px -3px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 4px 6px -3px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 8px 10px -3px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0px 5px 10px -2px hsl(0 0% 0% / 0.25);
  }

}
